CREATE OR REPLACE FUNCTION public.pm_phase_a_financial_file_gate(_bucket text,_name text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; BEGIN IF NOT public.pm_project_access_cutover_active() THEN RETURN true; END IF; FOR r IN SELECT created_project_id AS project_id,source_project_expense_id AS expense_id,direction::text AS direction FROM public.financial_document_review_queue WHERE source_bucket=_bucket AND (source_file_url=_name OR split_of_file_url=_name) UNION SELECT project_id,project_expense_id,direction::text FROM public.financial_documents WHERE _bucket='financial-documents' AND file_path=_name LOOP IF NOT public.pm_phase_a_queue_gate(r.project_id,r.expense_id,r.direction) THEN RETURN false; END IF; END LOOP; RETURN true; END $$;